  assertCan(actor, "issue:read", orgResource(input.orgId));
  const page = await issueRepo.listIssues(input);
  const visible = await Promise.all(page.items.map(async (issue) => {
    const project = await projectRepo.findProjectById(input.orgId, issue.projectId);
